// DeviceGetName Returns an identifer string for the device.
//
// Wraps hipDeviceGetName.
func DeviceGetName(device Device) (string, error) {
	if err := checkLib(); err != nil {
		return "", err
	}
	var buf_ [256]byte
	if err := toError(fnDeviceGetName(&buf_[0], int32(len(buf_)), device)); err != nil {
		return "", err
	}
	n := 0
	for n < len(buf_) && buf_[n] != 0 {
		n++
	}
	return string(buf_[:n]), nil
}

